/* Madurese Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ahmad": "most praised — Arabic", "Siti": "lady — Arabic sayyidati", "Muhammad": "praised — Arabic", "Fatimah": "A beloved feminine name, borne by the Prophet's daughter.", "Hasan": "handsome, good — Arabic", "Zainab": "A popular feminine name in Madura.", "No hereditary surnames": "The Madurese traditionally use single given names with no inherited family surname.", "Bin and Binti": "Madurese names connect generations with bin (son of) and binti (daughter of).", "Haji and Hajjah": "Honorifics placed before the name of pilgrims, functioning almost like titles.", "Achmad Fauzi": "A typical Madurese name string: Arabic given names in sequence, no surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ahmad';
console.log(lookup(q));

